        sheets.load(sheetId);
        SheetSetting setting = settings.findBySheetIdAndKey(sheetId, POT).orElse(null);
        try {
            if (value == null) {
                if (setting != null) {
                    settings.delete(setting);
                    settings.flush();
                }
            } else if (setting == null) {
                settings.saveAndFlush(new SheetSetting(sheetId, POT, value.toPlainString()));
